"""Vectorized independent reference for SHTOOLS gradient-tensor grids.

Computes the Cartesian Hessian of the potential by high-order finite
differences and projects it onto the local north/west/up frame.
Nothing from SHTOOLS is used.
"""
import numpy as np


def read_cilm(path, lmax):
    c = np.zeros((2, lmax + 1, lmax + 1))
    for line in open(path):
        p = line.split()
        if not p:
            continue
        l, m = int(p[0]), int(p[1])
        if l <= lmax:
            c[0, l, m] = float(p[2])
            c[1, l, m] = float(p[3])
    return c


def schmidt_vec(lmax, x):
    """Schmidt semi-normalized P[l,m](x) for array x. Returns (lmax+1,lmax+1)+x.shape."""
    x = np.asarray(x, dtype=float)
    P = np.zeros((lmax + 1, lmax + 1) + x.shape)
    s = np.sqrt(np.maximum(0.0, 1.0 - x * x))
    P[0, 0] = 1.0
    if lmax >= 1:
        P[1, 1] = s
    for m in range(2, lmax + 1):
        P[m, m] = np.sqrt((2.0 * m - 1.0) / (2.0 * m)) * s * P[m - 1, m - 1]
    for m in range(0, lmax + 1):
        if m + 1 <= lmax:
            P[m + 1, m] = np.sqrt(2.0 * m + 1.0) * x * P[m, m]
        for l in range(m + 2, lmax + 1):
            a = np.sqrt(float((l - 1) ** 2 - m * m))
            b = np.sqrt(float(l * l - m * m))
            P[l, m] = ((2.0 * l - 1.0) * x * P[l - 1, m] - a * P[l - 2, m]) / b
    return P


def potential(cilm, lmax, r0, X, Y, Z, kind="mag", gm=1.0):
    r = np.sqrt(X * X + Y * Y + Z * Z)
    ct = Z / r
    lon = np.arctan2(Y, X)
    P = schmidt_vec(lmax, ct)
    v = np.zeros(np.shape(r))
    ratio = r0 / r
    for l in range(0, lmax + 1):
        norm = np.sqrt(2.0 * l + 1.0) if kind == "grav" else 1.0
        acc = np.zeros(np.shape(r))
        for m in range(0, l + 1):
            g, h = cilm[0, l, m], cilm[1, l, m]
            if g == 0.0 and h == 0.0:
                continue
            trig = g * np.cos(m * lon) + h * np.sin(m * lon)
            acc = acc + trig * P[l, m]
        if kind == "grav":
            v = v + ratio ** l * acc * norm
        else:
            v = v + ratio ** (l + 1) * acc
    if kind == "grav":
        return gm / r * v
    return r0 * v


def frames(lat_deg, lon_deg):
    la = np.radians(lat_deg)
    lo = np.radians(lon_deg)
    up = np.stack([np.cos(la) * np.cos(lo), np.cos(la) * np.sin(lo), np.sin(la)], axis=-1)
    north = np.stack([-np.sin(la) * np.cos(lo), -np.sin(la) * np.sin(lo), np.cos(la)], axis=-1)
    west = np.stack([np.sin(lo), -np.cos(lo), np.zeros_like(lo)], axis=-1)
    return north, west, up


def r_ellipsoid(a, f, lat_deg):
    la = np.radians(lat_deg)
    return a * np.sqrt(1.0 / (np.cos(la) ** 2 + np.sin(la) ** 2 / (1.0 - f) ** 2))


def reference(cilm, lmax, r0, a, f, lat, lon, kind="mag", gm=1.0, h=250.0):
    """Return dict of reference tensor components and field components."""
    lat = np.asarray(lat, dtype=float)
    lon = np.asarray(lon, dtype=float)
    north, west, up = frames(lat, lon)
    r = r_ellipsoid(a, f, lat)
    p = r[..., None] * up

    def V(off):
        q = p + off
        return potential(cilm, lmax, r0, q[..., 0], q[..., 1], q[..., 2], kind, gm)

    e = np.eye(3)
    H = np.zeros(lat.shape + (3, 3))
    w1 = {-2: 1.0, -1: -8.0, 1: 8.0, 2: -1.0}
    for i in range(3):
        vals = {k: V(k * h * e[i]) for k in (-2, -1, 0, 1, 2)}
        H[..., i, i] = (-vals[-2] + 16 * vals[-1] - 30 * vals[0]
                        + 16 * vals[1] - vals[2]) / (12 * h * h)
    for i in range(3):
        for j in range(i + 1, 3):
            acc = np.zeros(lat.shape)
            for ka, wa in w1.items():
                for kb, wb in w1.items():
                    acc = acc + wa * wb * V(ka * h * e[i] + kb * h * e[j])
            H[..., i, j] = H[..., j, i] = acc / (144.0 * h * h)

    def proj(u, v):
        return np.einsum('...i,...ij,...j->...', u, H, v)

    grad = np.zeros(lat.shape + (3,))
    for i in range(3):
        grad[..., i] = (-V(2 * h * e[i]) + 8 * V(h * e[i]) - 8 * V(-h * e[i])
                        + V(-2 * h * e[i])) / (12 * h)
    if kind == "mag":
        B = -grad
    else:
        B = grad
    out = {
        'vxx': proj(north, north), 'vyy': proj(west, west), 'vzz': proj(up, up),
        'vxy': proj(north, west), 'vxz': proj(north, up), 'vyz': proj(west, up),
        'rad': np.einsum('...i,...i->...', B, up),
        'theta': -np.einsum('...i,...i->...', B, north),
        'phi': -np.einsum('...i,...i->...', B, west),
    }
    out['total'] = np.sqrt(out['rad'] ** 2 + out['theta'] ** 2 + out['phi'] ** 2)
    return out
